-- NOTI ICE | Oferta ICE 2027-1 (MySQL 8 / ASP.NET Core 8)
-- PREPARADO; NO EJECUTAR SIN AUTORIZACION ADICIONAL.
-- Unico destino: portal_noticias_pruebas. NUNCA portal_noticias.
-- Fuente institucional: 176 grupos, de ellos 173 nuevos; conserva 1CM10, 1CM13.
-- ProgramaId 3, rotulado Plan 2009 en ESIME => Plan 2004 en NOTI ICE
-- (equivalencia indicada por el responsable del proyecto; CSV conserva original).
-- ProgramaId 4 => Plan 2024. El grupo 2CM7 SIN UNIDADES se excluye.
-- Idempotencia: solo agrega grupos nuevos y sus hijos en la misma transacción;
-- nunca altera IDs ni suscripciones previamente existentes, no DELETE/UPDATE/DROP permanentes.
-- El catálogo agrega solo nombres faltantes; no certifica claves IPN.
-- Requiere cliente MySQL SIN --force; ante cualquier error interrumpir y ROLLBACK.
-- La DDL TEMPORARY es local a la sesión; no se crean tablas permanentes nuevas.
-- NO se cambian controles JWT, audiencias, publicaciones ni la base original.
USE `portal_noticias_pruebas`;
SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_guard`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_newgroups`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_docentes`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_sesiones`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_unidades`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_grupos`;
DROP TEMPORARY TABLE IF EXISTS `tmp_noti_ice_catalogo`;

CREATE TEMPORARY TABLE `tmp_noti_ice_grupos` (
 `SourceId` VARCHAR(40) NOT NULL PRIMARY KEY,
 `CodigoGrupo` VARCHAR(30) NOT NULL,
 `Programa` VARCHAR(180) NOT NULL,
 `Plan` VARCHAR(10) NOT NULL,
 `Semestre` INT NOT NULL,
 `Turno` VARCHAR(50),
 `Modalidad` VARCHAR(80),
 `Especialidad` VARCHAR(120),
 `UrlFuente` VARCHAR(500),
 `FechaActualizacionFuente` DATE,
 `ChecksumFuente` CHAR(64),
 UNIQUE KEY `ux_stg_identidad` (`Programa`,`Plan`,`CodigoGrupo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE `tmp_noti_ice_unidades` (
 `SourceId` VARCHAR(40) NOT NULL PRIMARY KEY,
 `SourceGrupoId` VARCHAR(40) NOT NULL,
 `OrdenFuente` INT NOT NULL,
 `NombrePublicado` VARCHAR(180) NOT NULL,
 `EsLaboratorio` TINYINT NOT NULL,
 `AulaPublicada` VARCHAR(120),
 UNIQUE KEY `ux_stg_unidad_orden` (`SourceGrupoId`,`OrdenFuente`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE `tmp_noti_ice_sesiones` (
 `SourceUnidadId` VARCHAR(40) NOT NULL,
 `DiaSemana` INT NOT NULL,
 `HoraInicio` TIME NOT NULL,
 `HoraFin` TIME NOT NULL,
 `Aula` VARCHAR(120),
 PRIMARY KEY (`SourceUnidadId`,`DiaSemana`,`HoraInicio`,`HoraFin`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE `tmp_noti_ice_docentes` (
 `SourceUnidadId` VARCHAR(40) NOT NULL,
 `Orden` INT NOT NULL,
 `NombrePublicado` VARCHAR(180),
 `Tipo` VARCHAR(10) NOT NULL,
 PRIMARY KEY (`SourceUnidadId`,`Orden`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE `tmp_noti_ice_catalogo` (
 `IdOrigen` VARCHAR(180) NOT NULL PRIMARY KEY,
 `Plan` VARCHAR(10) NOT NULL,
 `Semestre` INT NOT NULL,
 `NombrePublicado` VARCHAR(180) NOT NULL,
 UNIQUE KEY `ux_stg_cat_nombre` (`Plan`,`Semestre`,`NombrePublicado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE `tmp_noti_ice_newgroups` (
 `SourceId` VARCHAR(40) NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- El CHECK funciona como condición de parada sin escribir en tablas reales.
CREATE TEMPORARY TABLE `tmp_noti_ice_guard` (
 `Valido` INT NOT NULL,
 CONSTRAINT `chk_noti_guard` CHECK (`Valido` = 1)
) ENGINE=InnoDB;





































-- INSPECCION DE STAGING, ANTES DE ESCRIBIR EN TABLAS DEL PORTAL.
SELECT 'GRUPOS_NUEVOS_STAGING' AS Indicador, COUNT(*) AS Total FROM `tmp_noti_ice_grupos`
UNION ALL SELECT 'UNIDADES_STAGING', COUNT(*) FROM `tmp_noti_ice_unidades`
UNION ALL SELECT 'SESIONES_STAGING', COUNT(*) FROM `tmp_noti_ice_sesiones`
UNION ALL SELECT 'DOCENTES_STAGING', COUNT(*) FROM `tmp_noti_ice_docentes`
UNION ALL SELECT 'CATALOGO_STAGING', COUNT(*) FROM `tmp_noti_ice_catalogo`;

-- 1: validacion PREVIA sin reutilizar tablas TEMPORARY dentro de una misma sentencia.
-- ERROR 1137 corregido: cada calculo se ejecuta en su propia instruccion SELECT INTO.
-- Todas las variables son locales a esta conexion. No se escribe en tablas permanentes.
SET @ice27_base_ok := (DATABASE() = 'portal_noticias_pruebas');
SELECT COUNT(*) INTO @ice27_periodos_activos FROM `ofertaperiodos`
WHERE `Clave`='2027-1' AND `Activo`=b'1';
SELECT COUNT(*) INTO @ice27_grupos FROM `tmp_noti_ice_grupos`;
SELECT COUNT(*) INTO @ice27_unidades FROM `tmp_noti_ice_unidades`;
SELECT COUNT(*) INTO @ice27_sesiones FROM `tmp_noti_ice_sesiones`;
SELECT COUNT(*) INTO @ice27_docentes FROM `tmp_noti_ice_docentes`;
SELECT COUNT(*) INTO @ice27_catalogo FROM `tmp_noti_ice_catalogo`;

-- Integridad del staging: cada tabla temporal participa una sola vez por sentencia.
SELECT COUNT(*) INTO @ice27_unidades_sin_grupo
FROM `tmp_noti_ice_unidades` u
LEFT JOIN `tmp_noti_ice_grupos` g ON g.SourceId=u.SourceGrupoId
WHERE g.SourceId IS NULL;
SELECT COUNT(*) INTO @ice27_sesiones_sin_unidad
FROM `tmp_noti_ice_sesiones` s
LEFT JOIN `tmp_noti_ice_unidades` u ON u.SourceId=s.SourceUnidadId
WHERE u.SourceId IS NULL;
SELECT COUNT(*) INTO @ice27_docentes_sin_unidad
FROM `tmp_noti_ice_docentes` d
LEFT JOIN `tmp_noti_ice_unidades` u ON u.SourceId=d.SourceUnidadId
WHERE u.SourceId IS NULL;
SELECT COUNT(*) INTO @ice27_unidades_sin_catalogo
FROM `tmp_noti_ice_unidades` u
JOIN `tmp_noti_ice_grupos` g ON g.SourceId=u.SourceGrupoId
LEFT JOIN `tmp_noti_ice_catalogo` c
  ON c.Plan=g.Plan AND c.Semestre=g.Semestre AND c.NombrePublicado=u.NombrePublicado
WHERE c.IdOrigen IS NULL;
SELECT COUNT(*) INTO @ice27_grupos_conflicto
FROM `tmp_noti_ice_grupos` sg
JOIN `ofertaperiodos` p ON p.Clave='2027-1'
JOIN `ofertagrupos` g
  ON g.idPeriodo=p.idPeriodo AND g.Plan=sg.Plan AND g.CodigoGrupo=sg.CodigoGrupo
WHERE g.Programa<>sg.Programa OR g.Semestre<>sg.Semestre;
SELECT COUNT(*) INTO @ice27_catalogo_conflicto
FROM `tmp_noti_ice_catalogo` s
JOIN `catalogomateriasplanes` c ON c.IdOrigen=s.IdOrigen
WHERE c.Plan<>s.Plan OR c.Semestre<>s.Semestre OR c.Nombre<>s.NombrePublicado;

-- CHECK(Valido=1) provoca detencion antes de START TRANSACTION si algo no coincide.
-- MySQL CLI: ejecutar sin --force y con --skip-reconnect, como antes.
SELECT CASE WHEN
 @ice27_base_ok=1
 AND @ice27_periodos_activos=1
 AND @ice27_grupos=173
 AND @ice27_unidades=1697
 AND @ice27_sesiones=3165
 AND @ice27_docentes=2382
 AND @ice27_catalogo=191
 AND @ice27_unidades_sin_grupo=0
 AND @ice27_sesiones_sin_unidad=0
 AND @ice27_docentes_sin_unidad=0
 AND @ice27_unidades_sin_catalogo=0
 AND @ice27_grupos_conflicto=0
 AND @ice27_catalogo_conflicto=0
 THEN 1 ELSE 0 END;

-- ADVERTENCIA: no confirma que 1CM10/1CM13 sean idénticos a la nueva fuente.
-- No se alteran sus registros o suscripciones bajo ninguna circunstancia.
-- Todas las DML persistentes siguientes son INSERT, jamás UPDATE/DELETE.
START TRANSACTION;

-- Capturar identidad de grupos AUN NO existentes. En reejecución correcta: 0.
SELECT sg.SourceId FROM `tmp_noti_ice_grupos` sg
JOIN `ofertaperiodos` p ON p.Clave='2027-1'
LEFT JOIN `ofertagrupos` g ON g.idPeriodo=p.idPeriodo AND g.Programa=sg.Programa AND g.Plan=sg.Plan AND g.CodigoGrupo=sg.CodigoGrupo
WHERE g.idGrupoOferta IS NULL;

-- Catálogo provisional, sin inventar claves IPN ni modificar registros existentes.
SELECT s.IdOrigen,NULL,NULL,b'0',NULL,NULL,s.NombrePublicado,s.Plan,
 'Ingeniería en Comunicaciones y Electrónica',s.Semestre,NULL,NULL,NULL,b'1'
FROM `tmp_noti_ice_catalogo` s
WHERE NOT EXISTS (
 SELECT 1 FROM `catalogomateriasplanes` c
 WHERE c.Plan=s.Plan AND c.Semestre=s.Semestre AND
 c.Programa='Ingeniería en Comunicaciones y Electrónica' AND c.Nombre=s.NombrePublicado
);

-- Solo grupos nuevos; se preservan todas las PK y filas anteriores.
SELECT p.idPeriodo,sg.CodigoGrupo,sg.Programa,sg.Plan,sg.Semestre,sg.Turno,sg.Modalidad,sg.Especialidad,b'0',sg.UrlFuente,sg.FechaActualizacionFuente,CURRENT_TIMESTAMP,sg.ChecksumFuente,b'1'
FROM `tmp_noti_ice_newgroups` ng
JOIN `tmp_noti_ice_grupos` sg ON sg.SourceId=ng.SourceId
JOIN `ofertaperiodos` p ON p.Clave='2027-1';

-- Asociar cada unidad al catálogo existente o nuevo, con nombre y plan exactos.
SELECT g.idGrupoOferta,u.NombrePublicado,u.EsLaboratorio,u.AulaPublicada,
 (
  SELECT MIN(c.idMateriaCatalogo) FROM `catalogomateriasplanes` c
  WHERE c.Plan=sg.Plan AND c.Semestre=sg.Semestre AND c.Programa=sg.Programa AND c.Nombre=u.NombrePublicado
 ),u.OrdenFuente
FROM `tmp_noti_ice_unidades` u
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId
JOIN `tmp_noti_ice_grupos` sg ON sg.SourceId=ng.SourceId
JOIN `ofertaperiodos` p ON p.Clave='2027-1'
JOIN `ofertagrupos` g ON g.idPeriodo=p.idPeriodo AND g.Programa=sg.Programa AND g.Plan=sg.Plan AND g.CodigoGrupo=sg.CodigoGrupo;

SELECT ou.idUnidadOferta,s.DiaSemana,s.HoraInicio,s.HoraFin,s.Aula
FROM `tmp_noti_ice_sesiones` s
JOIN `tmp_noti_ice_unidades` u ON u.SourceId=s.SourceUnidadId
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId
JOIN `tmp_noti_ice_grupos` sg ON sg.SourceId=ng.SourceId
JOIN `ofertaperiodos` p ON p.Clave='2027-1'
JOIN `ofertagrupos` g ON g.idPeriodo=p.idPeriodo AND g.Programa=sg.Programa AND g.Plan=sg.Plan AND g.CodigoGrupo=sg.CodigoGrupo
JOIN `ofertaunidades` ou ON ou.idGrupoOferta=g.idGrupoOferta AND ou.OrdenFuente=u.OrdenFuente;

SELECT ou.idUnidadOferta,d.Orden,d.NombrePublicado,d.Tipo
FROM `tmp_noti_ice_docentes` d
JOIN `tmp_noti_ice_unidades` u ON u.SourceId=d.SourceUnidadId
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId
JOIN `tmp_noti_ice_grupos` sg ON sg.SourceId=ng.SourceId
JOIN `ofertaperiodos` p ON p.Clave='2027-1'
JOIN `ofertagrupos` g ON g.idPeriodo=p.idPeriodo AND g.Programa=sg.Programa AND g.Plan=sg.Plan AND g.CodigoGrupo=sg.CodigoGrupo
JOIN `ofertaunidades` ou ON ou.idGrupoOferta=g.idGrupoOferta AND ou.OrdenFuente=u.OrdenFuente;

-- 2: validacion FINAL sin reabrir TEMPORARY varias veces en una sentencia.
-- Se verifica numero de grupos NUEVOS y TODOS los hijos de esos grupos.
-- Si una verificacion falla, CHECK(Valido=1) detiene el cliente ANTES de COMMIT.
-- El cliente debe cerrar la conexion sin --force, lo cual revierte INSERT no confirmados.
SELECT COUNT(*) INTO @ice27_nuevos_esperados FROM `tmp_noti_ice_newgroups`;

SELECT COUNT(*) INTO @ice27_nuevos_en_mysql
FROM `ofertagrupos` g
JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo AND p.Clave='2027-1'
JOIN `tmp_noti_ice_grupos` sg
  ON sg.CodigoGrupo=g.CodigoGrupo AND sg.Plan=g.Plan AND sg.Programa=g.Programa
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=sg.SourceId;

SELECT COUNT(*) INTO @ice27_unidades_esperadas
FROM `tmp_noti_ice_unidades` u
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId;

SELECT COUNT(*) INTO @ice27_unidades_en_mysql
FROM `ofertaunidades` ou
JOIN `ofertagrupos` g ON g.idGrupoOferta=ou.idGrupoOferta
JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo AND p.Clave='2027-1'
JOIN `tmp_noti_ice_grupos` sg
  ON sg.CodigoGrupo=g.CodigoGrupo AND sg.Plan=g.Plan AND sg.Programa=g.Programa
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=sg.SourceId;

SELECT COUNT(*) INTO @ice27_sesiones_esperadas
FROM `tmp_noti_ice_sesiones` s
JOIN `tmp_noti_ice_unidades` u ON u.SourceId=s.SourceUnidadId
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId;

SELECT COUNT(*) INTO @ice27_sesiones_en_mysql
FROM `ofertasesiones` os
JOIN `ofertaunidades` ou ON ou.idUnidadOferta=os.idUnidadOferta
JOIN `ofertagrupos` g ON g.idGrupoOferta=ou.idGrupoOferta
JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo AND p.Clave='2027-1'
JOIN `tmp_noti_ice_grupos` sg
  ON sg.CodigoGrupo=g.CodigoGrupo AND sg.Plan=g.Plan AND sg.Programa=g.Programa
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=sg.SourceId;

SELECT COUNT(*) INTO @ice27_docentes_esperados
FROM `tmp_noti_ice_docentes` d
JOIN `tmp_noti_ice_unidades` u ON u.SourceId=d.SourceUnidadId
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=u.SourceGrupoId;

SELECT COUNT(*) INTO @ice27_docentes_en_mysql
FROM `ofertadocentesunidad` od
JOIN `ofertaunidades` ou ON ou.idUnidadOferta=od.idUnidadOferta
JOIN `ofertagrupos` g ON g.idGrupoOferta=ou.idGrupoOferta
JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo AND p.Clave='2027-1'
JOIN `tmp_noti_ice_grupos` sg
  ON sg.CodigoGrupo=g.CodigoGrupo AND sg.Plan=g.Plan AND sg.Programa=g.Programa
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=sg.SourceId;

-- Una comprobacion adicional protege la vinculacion con el catalogo:
-- las unidades nuevas deben quedar con idMateriaCatalogo resuelto.
SELECT COUNT(*) INTO @ice27_unidades_sin_id_catalogo
FROM `ofertaunidades` ou
JOIN `ofertagrupos` g ON g.idGrupoOferta=ou.idGrupoOferta
JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo AND p.Clave='2027-1'
JOIN `tmp_noti_ice_grupos` sg
  ON sg.CodigoGrupo=g.CodigoGrupo AND sg.Plan=g.Plan AND sg.Programa=g.Programa
JOIN `tmp_noti_ice_newgroups` ng ON ng.SourceId=sg.SourceId
WHERE ou.idMateriaCatalogo IS NULL;

-- Nunca se confirma una transaccion con cantidades inconsistentes.
SELECT CASE WHEN
 @ice27_nuevos_esperados=@ice27_nuevos_en_mysql
 AND @ice27_unidades_esperadas=@ice27_unidades_en_mysql
 AND @ice27_sesiones_esperadas=@ice27_sesiones_en_mysql
 AND @ice27_docentes_esperados=@ice27_docentes_en_mysql
 AND @ice27_unidades_sin_id_catalogo=0
 THEN 1 ELSE 0 END;

-- SOLO LUEGO DE APROBACION EXPLICITA Y RESPALDO ACTUALIZADO:
COMMIT;

SELECT 'GRUPOS_NUEVOS_ESTA_EJECUCION' AS Indicador, COUNT(*) AS Cantidad FROM `tmp_noti_ice_newgroups`;
SELECT p.Clave,g.Plan,COUNT(*) AS GruposActivos FROM `ofertagrupos` g JOIN `ofertaperiodos` p ON p.idPeriodo=g.idPeriodo
WHERE p.Clave='2027-1' AND g.Activo=b'1' AND g.Programa='Ingeniería en Comunicaciones y Electrónica'
GROUP BY p.Clave,g.Plan ORDER BY g.Plan;
-- Comprobaciones adicionales en 00_PREVALIDACION_SOLO_LECTURA.sql

